from pathlib import Path
import json,math,sys,datetime
source,out=map(Path,sys.argv[1:3]);r=json.loads(source.read_text(encoding='utf-8'))
if out.exists():raise SystemExit('Refuse prior evidence overwrite')
def sdf(x,y,cx,cy,hx,hy,rad):
 qx=abs(x-cx)-hx+rad;qy=abs(y-cy)-hy+rad
 return math.hypot(max(qx,0),max(qy,0))+min(max(qx,qy),0)-rad
boundaries=[{'frame':1,'edge':'outer','sdf_args':[224,224,128,128,48]},{'frame':1,'edge':'inner','sdf_args':[224,224,88,88,8]},{'frame':2,'edge':'outer','sdf_args':[288,288,128,128,48]},{'frame':2,'edge':'inner','sdf_args':[288,288,88,88,8]}]
points=[]
for v in r['full_actual_mismatch_list']:
 x,y=v['xy'];d=[abs(sdf(x+.5,y+.5,*b['sdf_args']))for b in boundaries];n=min(range(4),key=lambda i:d[i]);points.append({**v,'nearest_analytic_boundary':{'frame':boundaries[n]['frame'],'edge':boundaries[n]['edge']},'pixel_center_distance_to_boundary':d[n],'within_half_pixel_diagonal':d[n]<=math.sqrt(.5)})
exceptions=[v for v in points if not v['both_partial_alpha']]
result={'task_id':'A13','reviewer':'a10_audit_resume','measured_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_difference_report':str(source.resolve()),'original_raw_alpha_equal_false_preserved':r['raw_alpha_arrays_exactly_equal']is False,'original_both_partial_test_false_preserved':r['all_mismatches_are_both_partial_aa']is False,'strict_test_explanation':'Both-partial predicate excludes8 outer AA fringe points where coloralpha0,blackalpha1. Its earlier non_aa_difference_count name does not prove these8 points are non-AA; this supplement independently checks analytic edge position.','actual_alpha_difference_count':len(points),'max_alpha_delta':max(abs(v['alpha_delta'])for v in points),'full_opacity_difference_count':sum(v['color_rgba'][3]==255 or v['black_rgba'][3]==255 for v in points),'threshold128_geometry_mask_equal':r['binary_alpha_ge128_mask_exactly_equal'],'alpha_gt0_support_equal':not exceptions,'support_differences_0_vs1':exceptions,'max_analytic_boundary_distance':max(v['pixel_center_distance_to_boundary']for v in points),'all_mismatches_within_half_pixel_diagonal':all(v['within_half_pixel_diagonal']for v in points),'analytic_model':'Actual DSL two outer256x256 R48 and inner176x176 R8 hollow-square boundaries, centers224/288; ring thickness40. Pixel centers used.','aa_exception_evidence_confirmed':all(v['within_half_pixel_diagonal']for v in points)and max(abs(v['alpha_delta'])for v in points)==1,'all_point_evidence':points,'interpretation':'All154 differences lie on analytic AA boundary within one pixel footprint;8 support differences are0/1 fringes. No changes to PNG or tolerance in raw exact-alpha test. DSL geometry equal and threshold128 silhouette equal satisfy task geometric requirement with expressly allowed AA alpha.'}
out.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({k:v for k,v in result.items()if k not in ['all_point_evidence','support_differences_0_vs1']},indent=2))
